t.script:
// MICROSITES: Redirigir clicks a los dominios de los comercios
(function(){
    function redirectToMicrosites(){
        document.querySelectorAll('[data-merchant-domain]').forEach(function(el){
            var domain = el.getAttribute('data-merchant-domain');
            if(!domain) return;
            var links = el.querySelectorAll('a[href*="/shop/"]');
            links.forEach(function(a){
                var href = a.getAttribute('href');
                if(!href || href.indexOf(domain) !== -1) return;
                var match = href.match(/\/shop\/([^?#]+)/);
                if(match){
                    a.href = domain.replace(/\/$/, '') + '/shop/' + match[1];
                    a.target = '_blank';
                }
            });
        });
    }

    if(document.readyState !== 'loading'){
        redirectToMicrosites();
    } else {
        document.addEventListener('DOMContentLoaded', redirectToMicrosites);
    }
    window.addEventListener('load', redirectToMicrosites);
})();

                    (function() {
// console.log('[ZONE-CAT] Script iniciado');

                        function initSelect2() {
// console.log('[ZONE-CAT] initSelect2 llamado');

                            if (!window.location.pathname.startsWith('/shop')) {
// console.log('[ZONE-CAT] No estamos en /shop, saliendo');
                                return;
                            }

                            if (!window.jQuery) {
// console.log('[ZONE-CAT] jQuery no disponible');
                                return;
                            }

                            var $ = window.jQuery;
                            var $select = $('#zone-category-select');

// console.log('[ZONE-CAT] Select encontrado:', $select.length);

                            if (!$select.length) {
// console.log('[ZONE-CAT] Select no encontrado');
                                return;
                            }

                            if ($select.hasClass('select2-hidden-accessible')) {
// console.log('[ZONE-CAT] Select2 ya inicializado');
                                return;
                            }

                            // Inicializar Select2
// console.log('[ZONE-CAT] Inicializando Select2...');
                            $select.select2({
                                theme: 'bootstrap-5',
                                width: '100%',
                                placeholder: 'Buscar categoria...',
                                allowClear: false,
                                minimumResultsForSearch: 0,
                                language: {
                                    noResults: function() { return "No se encontro la categoria"; },
                                    searching: function() { return "Buscando..."; }
                                }
                            });

// console.log('[ZONE-CAT] Select2 inicializado');

                            // SIEMPRE usar AJAX, nunca navegar directamente
                            $select.off('change').on('change', function(e) {
// console.log('[ZONE-CAT] Evento change disparado');
                                var url = $(this).val();
// console.log('[ZONE-CAT] Valor del select:', url);

                                // Extraer category ID de la URL
                                var categoryId = null;
                                if (url && url.includes('category=')) {
                                    var match = url.match(/category=([0-9]+)/);
                                    if (match) categoryId = match[1];
                                }

                                // Usar ZoneAjaxLoader si está disponible
                                if (window.ZoneAjaxLoader) {
// console.log('[ZONE-CAT] Usando AJAX para categoria:', categoryId);
                                    var searchInput = document.querySelector('input[name="search"]');
                                    var search = searchInput ? searchInput.value : '';
                                    var minPrice = window.ZoneAjaxLoader.currentMinPrice || 0;
                                    var maxPrice = window.ZoneAjaxLoader.currentMaxPrice || 0;
                                    window.ZoneAjaxLoader.loadProducts(categoryId, search, minPrice, maxPrice);
                                } else {
// console.log('[ZONE-CAT] ZoneAjaxLoader no disponible');
                                }
                            });
                        }

                        // Función para seleccionar la categoría actual en el Select2
                        function selectCurrentCategory() {
                            var urlParams = new URLSearchParams(window.location.search);
                            var categoryId = urlParams.get('category');
                            if (categoryId) {
                                var $select = $('#zone-category-select');
                                if ($select.length && $select.hasClass('select2-hidden-accessible')) {
                                    // Buscar la opción que contiene el category ID
                                    var found = false;
                                    $select.find('option').each(function() {
                                        var optionValue = $(this).val();
                                        if (optionValue && optionValue.includes('category=' + categoryId)) {
                                            $select.val(optionValue).trigger('change');
// console.log('[ZONE-CAT] Categoría actual seleccionada:', categoryId);
                                            found = true;
                                            return false;
                                        }
                                    });
                                    return found;
                                }
                            }
                            return false;
                        }

                        // Función global para actualizar Select2 desde el AJAX loader
                        window.updateSelect2WithCategory = function(categoryId, categoryName) {
// console.log('[ZONE-CAT] Actualizando Select2 con categoría:', categoryId, categoryName);
                            var $select = $('#zone-category-select');
                            if (!$select.length) return;

                            if (!categoryId) {
                                // Resetear a "Todas las categorías" (primera opción)
                                var firstOption = $select.find('option:first').val();
                                $select.val(firstOption).trigger('change');
                                return;
                            }

                            // Buscar la opción que corresponde a esta categoría
                            var found = false;
                            $select.find('option').each(function() {
                                var optionValue = $(this).val();
                                if (optionValue && optionValue.includes('category=' + categoryId)) {
                                    $select.val(optionValue).trigger('change');
// console.log('[ZONE-CAT] Select2 actualizado a:', optionValue);
                                    found = true;
                                    return false;
                                }
                            });

                            // Si no se encontró, crear una opción temporal (para categorías dinámicas)
                            if (!found && categoryName) {
                                var tempUrl = '/shop?category=' + categoryId;
                                var newOption = new Option(categoryName, tempUrl, true, true);
                                $select.append(newOption).trigger('change');
// console.log('[ZONE-CAT] Opción temporal creada para:', categoryName);
                            }
                        };

                        // Intentar inicializar múltiples veces
                        function tryInit() {
// console.log('[ZONE-CAT] Intentando inicializar...');
                            initSelect2();
                            // Después de inicializar, seleccionar la categoría actual
                            setTimeout(selectCurrentCategory, 100);
                        }

                        if (document.readyState !== 'loading') {
                            tryInit();
                        } else {
                            document.addEventListener('DOMContentLoaded', tryInit);
                        }

                        // Reintentar después de un tiempo
                        setTimeout(tryInit, 500);
                        setTimeout(tryInit, 1500);
                        setTimeout(tryInit, 3000);

                        // También intentar seleccionar la categoría cuando el DOM esté list
                        setTimeout(selectCurrentCategory, 1000);
                        setTimeout(selectCurrentCategory, 2500);

                    })();

                    (function() {
                        // AJAX para carga de productos sin recargar
                        window.ZoneAjaxLoader = {
                            isLoading: false,
                            currentMinPrice: 0,
                            currentMaxPrice: 0,

                            loadProducts: function(categoryId, search, minPrice, maxPrice) {
                                if (this.isLoading) return;
                                this.isLoading = true;

                                // Guardar valores actuales
                                this.currentMinPrice = minPrice || 0;
                                this.currentMaxPrice = maxPrice || 0;

                                // Buscar el elemento GRID interno (con las clases CSS de columnas)
                                // IMPORTANTE: No reemplazar el wrapper, solo el contenido interno
                                var grid = document.getElementById('o_wsale_products_grid');
                                if (!grid) {
                                    grid = document.querySelector('#products_grid .o_wsale_products_grid_table');
                                }
                                if (!grid) {
                                    grid = document.getElementById('products_grid');
                                }
                                if (!grid) {
                                    this.isLoading = false;
                                    return;
                                }

                                // Guardar contenido original para restaurar en caso de error
                                var originalContent = grid.innerHTML;

                                // Mostrar indicador de carga
                                var loaderHtml = '

Cargando productos...';
                                grid.innerHTML = loaderHtml;

                                // Preparar URL con parámetros
                                var url = '/shop/ajax/products';
                                var params = new URLSearchParams();
                                if (categoryId) params.append('category', categoryId);
                                if (search) params.append('search', search);
                                if (minPrice) params.append('min_price', minPrice);
                                if (maxPrice) params.append('max_price', maxPrice);
                                if (params.toString()) url += '?' + params.toString();

// console.log('[ZONE-AJAX] Fetching:', url);

                                // Hacer petición AJAX
                                fetch(url, {
                                    method: 'GET',
                                    headers: {
                                        'Accept': 'application/json',
                                    }
                                })
                                .then(function(response) {
                                    if (!response.ok) throw new Error('Network error: ' + response.status);
                                    return response.json();
                                })
                                .then(function(result) {
// console.log('[ZONE-AJAX] Response:', result);

                                    if (result.error) throw new Error(result.error);

                                    // Actualizar el grid con el HTML recibido
                                    if (result.html) {
                                        grid.innerHTML = result.html;

                                        // Actualizar contador si existe
                                        var counter = document.querySelector('.o_wsale_products_grid_header .o_wsale_products_grid_count');
                                        if (counter && result.count !== undefined) {
                                            counter.textContent = result.count + ' productos';
                                        }

                                        // Ocultar paginación original cuando hay filtros activos
                                        var pagination = document.querySelector('.o_wsale_products_grid_bottom, .pagination, .o_pager');
                                        if (pagination && result.filters_active) {
                                            pagination.style.display = 'none';
                                        } else if (pagination && !result.filters_active) {
                                            pagination.style.display = '';
                                        }

                                        // Mostrar indicador de filtros activos
                                        var existingFilterInfo = document.getElementById('zone-active-filters');
                                        if (existingFilterInfo) {
                                            existingFilterInfo.remove();
                                        }

                                        if (result.filters_active) {
                                            var filterInfoHtml = '
';
                                            filterInfoHtml += '
';
                                            filterInfoHtml += 'Mostrando ' + result.count + ' productos';

                                            var filterDetails = [];
                                            if (result.category_name) {
                                                filterDetails.push('categoría: ' + result.category_name + '');
                                            } else if (result.category_id) {
                                                filterDetails.push('categoría seleccionada');
                                            }
                                            if (result.search) filterDetails.push('búsqueda: "' + result.search + '"');
                                            if (result.price && (result.price.min || result.price.max)) {
                                                filterDetails.push('precio: ' + result.price.min + '€ - ' + result.price.max + '€');
                                            }

                                            if (filterDetails.length > 0) {
                                                filterInfoHtml += '(' + filterDetails.join(', ') + ')';
                                            }
                                            filterInfoHtml += '';
                                            filterInfoHtml += '';
                                            filterInfoHtml += 'Limpiar filtros';
                                            filterInfoHtml += '';

                                            grid.insertAdjacentHTML('beforebegin', filterInfoHtml);
                                        }

                                        // Re-inicializar redirección a microsites
                                        if (window.redirectToMicrosites) {
                                            window.redirectToMicrosites();
                                        }

                                        // Actualizar URL sin recargar
                                        var newUrl = categoryId ? '/shop?category=' + categoryId : '/shop';
                                        var urlParams = [];
                                        if (search) urlParams.push('search=' + encodeURIComponent(search));
                                        if (minPrice) urlParams.push('min_price=' + minPrice);
                                        if (maxPrice) urlParams.push('max_price=' + maxPrice);
                                        if (urlParams.length > 0) {
                                            newUrl += (newUrl.includes('?') ? '&' : '?') + urlParams.join('&');
                                        }
                                        window.history.pushState({category: categoryId, search: search, minPrice: minPrice, maxPrice: maxPrice}, '', newUrl);

                                        // ACTUALIZAR SELECT2 con la categoría seleccionada
                                        updateSelect2WithCategory(categoryId, result.category_name);

// console.log('[ZONE-AJAX] Productos actualizados:', result.count);
                                    } else {
                                        throw new Error('No HTML in response');
                                    }
                                })
                                .catch(function(error) {
// console.error('[ZONE-AJAX] Error:', error);
                                    // Restaurar contenido original
                                    grid.innerHTML = originalContent;
                                    // Fallback: recargar la página
                                    var fallbackUrl = categoryId ? '/shop?category=' + categoryId : '/shop';
                                    if (minPrice) fallbackUrl += (fallbackUrl.includes('?') ? '&' : '?') + 'min_price=' + minPrice;
                                    if (maxPrice) fallbackUrl += (fallbackUrl.includes('?') ? '&' : '?') + 'max_price=' + maxPrice;
                                    window.location.href = fallbackUrl;
                                })
                                .finally(function() {
                                    window.ZoneAjaxLoader.isLoading = false;
                                });
                            }
                        };

                        // Interceptar cambios de categoría
                        function setupAjaxCategoryChange() {
                            var select = document.getElementById('zone-category-select');
                            if (!select) {
// console.log('[ZONE-AJAX] Select no encontrado');
                                return;
                            }

                            // Remover el onchange inline
                            select.removeAttribute('onchange');

                            // Prevenir navegación por defecto del select
                            select.addEventListener('click', function(e) {
                                e.preventDefault();
                            }, true);

                            // Agregar listener AJAX
                            select.addEventListener('change', function(e) {
                                e.preventDefault();
                                e.stopPropagation();

                                var value = this.value;
                                var categoryId = null;

                                // Extraer category ID de la URL
                                if (value && value.includes('category=')) {
                                    var match = value.match(/category=([0-9]+)/);
                                    if (match) categoryId = match[1];
                                }

                                var searchInput = document.querySelector('input[name="search"]');
                                var search = searchInput ? searchInput.value : '';

                                // Obtener precios actuales
                                var minPrice = window.ZoneAjaxLoader.currentMinPrice;
                                var maxPrice = window.ZoneAjaxLoader.currentMaxPrice;

// console.log('[ZONE-AJAX] Cambio de categoría:', categoryId);
                                window.ZoneAjaxLoader.loadProducts(categoryId, search, minPrice, maxPrice);

                                return false;
                            });

// console.log('[ZONE-AJAX] Listener categoría configurado');
                        }

                        // Interceptar cambios en el filtro de precio de Odoo
                        function setupPriceFilterIntercept() {
                            // Múltiples selectores para encontrar el input de precio
                            var priceRange = document.getElementById('o_wsale_price_range');
                            if (!priceRange) {
                                priceRange = document.querySelector('input[name="price"]');
                            }
                            if (!priceRange) {
                                priceRange = document.querySelector('input[data-name="price"]');
                            }
                            if (!priceRange) {
                                priceRange = document.querySelector('input[type="hidden"][name*="price"]');
                            }

                            // Buscar el contenedor del filtro de precio
                            var priceFilterContainer = document.querySelector('.o_wsale_price_filter, .price-filter, #price-filter');

                            if (priceRange) {
// console.log('[ZONE-AJAX] Filtro de precio encontrado:', priceRange.id || priceRange.name);

                                // Función para aplicar filtro de precio
                                function applyPriceFilter() {
                                    var value = priceRange.value;
// console.log('[ZONE-AJAX] Aplicando filtro de precio:', value);

                                    // Parsear valor "min,max"
                                    var prices = value.split(',');
                                    var minPrice = parseFloat(prices[0]) || 0;
                                    var maxPrice = parseFloat(prices[1]) || 0;

                                    window.ZoneAjaxLoader.currentMinPrice = minPrice;
                                    window.ZoneAjaxLoader.currentMaxPrice = maxPrice;

                                    // Obtener categoría y búsqueda actuales
                                    var urlParams = new URLSearchParams(window.location.search);
                                    var categoryId = urlParams.get('category');
                                    var searchInput = document.querySelector('input[name="search"]');
                                    var search = searchInput ? searchInput.value : '';

                                    window.ZoneAjaxLoader.loadProducts(categoryId, search, minPrice, maxPrice);
                                }

                                // Método 1: Observar cambios en el atributo value
                                var observer = new MutationObserver(function(mutations) {
                                    mutations.forEach(function(mutation) {
                                        if (mutation.type === 'attributes' && mutation.attributeName === 'value') {
                                            applyPriceFilter();
                                        }
                                    });
                                });
                                observer.observe(priceRange, { attributes: true });

                                // Método 2: Escuchar evento change
                                priceRange.addEventListener('change', applyPriceFilter);

                                // Método 3: Escuchar evento input (para sliders)
                                priceRange.addEventListener('input', function(e) {
                                    // Solo actualizar sin hacer AJAX mientras se arrastra
                                    var value = priceRange.value;
                                    var prices = value.split(',');
                                    window.ZoneAjaxLoader.currentMinPrice = parseFloat(prices[0]) || 0;
                                    window.ZoneAjaxLoader.currentMaxPrice = parseFloat(prices[1]) || 0;
                                });

                                // Método 4: Interceptar cualquier botón dentro del filtro de precio
                                if (priceFilterContainer) {
                                    var buttons = priceFilterContainer.querySelectorAll('button, .btn, a');
                                    buttons.forEach(function(btn) {
                                        btn.addEventListener('click', function(e) {
                                            e.preventDefault();
                                            e.stopPropagation();
                                            applyPriceFilter();
                                        });
                                    });
                                }

                                // Método 5: Detectar cambios en inputs visibles de precio (min/max)
                                var minPriceInput = document.querySelector('input[name="min_price"], input#min_price');
                                var maxPriceInput = document.querySelector('input[name="max_price"], input#max_price');

                                if (minPriceInput) {
                                    minPriceInput.addEventListener('change', function() {
                                        var minPrice = parseFloat(this.value) || 0;
                                        var maxPrice = window.ZoneAjaxLoader.currentMaxPrice || 0;
                                        var urlParams = new URLSearchParams(window.location.search);
                                        var categoryId = urlParams.get('category');
                                        var searchInput = document.querySelector('input[name="search"]');
                                        var search = searchInput ? searchInput.value : '';
                                        window.ZoneAjaxLoader.loadProducts(categoryId, search, minPrice, maxPrice);
                                    });
                                }

                                if (maxPriceInput) {
                                    maxPriceInput.addEventListener('change', function() {
                                        var minPrice = window.ZoneAjaxLoader.currentMinPrice || 0;
                                        var maxPrice = parseFloat(this.value) || 0;
                                        var urlParams = new URLSearchParams(window.location.search);
                                        var categoryId = urlParams.get('category');
                                        var searchInput = document.querySelector('input[name="search"]');
                                        var search = searchInput ? searchInput.value : '';
                                        window.ZoneAjaxLoader.loadProducts(categoryId, search, minPrice, maxPrice);
                                    });
                                }

// console.log('[ZONE-AJAX] Filtro de precio configurado con múltiples métodos');
                            } else {
// console.log('[ZONE-AJAX] Filtro de precio no encontrado, reintentando...');
                            }
                        }

                        // Configurar cuando el DOM esté listo
                        if (document.readyState !== 'loading') {
                            setupAjaxCategoryChange();
                            setupPriceFilterIntercept();
                        } else {
                            document.addEventListener('DOMContentLoaded', function() {
                                setupAjaxCategoryChange();
                                setupPriceFilterIntercept();
                            });
                        }
                        setTimeout(setupAjaxCategoryChange, 500);
                        setTimeout(setupPriceFilterIntercept, 500);
                        setTimeout(setupAjaxCategoryChange, 1500);
                        setTimeout(setupPriceFilterIntercept, 1500);

                        // Prevenir submit del formulario de filtros (para evitar recarga de página)
                        function preventFormSubmit() {
                            var forms = document.querySelectorAll('form[action*="/shop"], #o_wsale_price_range_form, .o_wsale_filters_form');
                            forms.forEach(function(form) {
                                form.addEventListener('submit', function(e) {
                                    e.preventDefault();
                                    e.stopPropagation();
// console.log('[ZONE-AJAX] Form submit prevenido');
                                    return false;
                                });
                            });

                            // También interceptar clics en el área de filtros de precio
                            var priceFilterArea = document.querySelector('.o_wsale_price_filter, #o_wsale_price_range');
                            if (priceFilterArea) {
                                priceFilterArea.addEventListener('click', function(e) {
                                    // Si el clic viene de un input tipo range o slider
                                    if (e.target.tagName === 'INPUT' || e.target.closest('input[type="range"]')) {
                                        // Dejar que el slider funcione normalmente
                                        return;
                                    }
                                    // Para otros elementos, prevenir navegación
                                    if (e.target.tagName === 'A' || e.target.closest('a')) {
                                        e.preventDefault();
                                    }
                                }, true);
                            }
                        }

                        if (document.readyState !== 'loading') {
                            preventFormSubmit();
                        } else {
                            document.addEventListener('DOMContentLoaded', preventFormSubmit);
                        }
                        setTimeout(preventFormSubmit, 1000);

                    })();
